package com.pratyush.orbitmobile.networking.pairing

import com.pratyush.orbitmobile.core.common.OrbitResult
import com.pratyush.orbitmobile.domain.model.Device

/**
 * Interface contract for decoding and authenticating QR codes generated by ORBIT Windows.
 */
interface QrPairingManager {
    suspend fun parsePairingQrCode(qrRawContent: String): OrbitResult<Device>
    suspend fun generateVerificationChallenge(): String
}
